#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int T;
    cin >> T;

    for (int t = 0; t < T; ++t) {
        unsigned n_A, n_B, n_C;
        cin >> n_A >> n_B >> n_C;
        cout << min({n_A, n_C, (n_A + n_B + n_C) / 3}) << endl;
    }
    return 0;
}

def solve():
    a, b, c = map(int, input().split())

    def f(m):
        if m > min(a, c):
            return False
        rem = (a - m) + (c - m) + b
        return rem >= m

    ng, ok = 10**10, -1
    while ng - ok > 1:
        mid = (ok + ng) // 2
        if f(mid):
            ok = mid
        else:
            ng = mid
    print(ok)


for _ in range(int(input())):
    solve()
